const activeAudioMix=()=>{const profile=store.getState().profile,mix=normalizeAudioMix(profile.audioMix||getAudioMix());return profile.audio===false?{music:0,voices:0,effects:0}:mix};
function speak(id,{once=false}={}){const key=`lh-voice-${id}`;if(once&&sessionStorage.getItem(key))return Promise.resolve({played:false,reason:"already-played"});if(once)sessionStorage.setItem(key,"1");const mix=activeAudioMix();return playVoiceLine(voiceManifest,id,{enabled:mix.voices>0,volume:mix.voices/100,onState:duckMusic})}
function cinematic(id){const mix=activeAudioMix();return playCinematicCue(cinematicManifest,id,{reduceMotion:store.getState().profile.accessibility.reduceMotion,volume:mix.effects/100,onState:duckMusic})}

function toast(message,type="ok"){const el=document.createElement("div");el.className=`toast ${type}`;el.textContent=message;toastRegion.append(el);setTimeout(()=>el.remove(),3200)}
function audioCue(type="select"){
  const volume=activeAudioMix().effects/100;if(volume<=0)return;
  try{const Ctx=window.AudioContext||window.webkitAudioContext,ctx=new Ctx(),o=ctx.createOscillator(),g=ctx.createGain();o.type="sine";o.frequency.value=type==="alarm"?190:type==="success"?620:420;g.gain.setValueAtTime(.055*volume,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.16);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.17)}catch{}
}
