  const go=(nextAct,nextRoute,title,detail)=>{store.update(x=>{x.campaign.act=Math.max(x.campaign.act,nextAct);x.campaign.decisions.push({title,detail})},title);outcomeModal(route,nextRoute)};
  document.querySelectorAll("[data-policy]").forEach(b=>b.addEventListener("click",()=>{const p=b.dataset.policy;store.update(x=>{x.campaign.flags.publicPolicy=p;if(p==="transparent"){x.agency.support+=15;x.agency.politicalCapital-=5}else if(p==="controlled"){x.agency.support+=7;x.economy.available+=6}else{x.economy.available+=16;x.agency.support-=8}x.campaign.act=1;x.campaign.decisions.push({title:"Política de transparência",detail:p})},"Mandato de reativação aprovado");outcomeModal("agency","design")}));
  document.querySelectorAll("[data-engineering-option]").forEach(b=>b.addEventListener("click",()=>{const current=store.getState(),session=engineeringData.sessions.find(item=>!(current.engineering?.locked||[]).includes(item.id));if(!session)return;store.update(x=>{x.engineering.drafts[session.id]=b.dataset.engineeringOption;x.engineering.consulted=[];x.ui.advisorMessage="Proposta aberta para parecer técnico e assinatura."},`Proposta em análise: ${b.dataset.engineeringOption}`);audioCue("select")}));
  one("[data-engineering-recovery]","click",()=>{const current=store.getState(),session=engineeringData.sessions.find(item=>!(current.engineering?.locked||[]).includes(item.id)),componentId=session&&current.engineering?.drafts?.[session.id],option=session?.options.find(item=>item.componentId===componentId),component=session&&data.components[session.id]?.find(item=>item.id===componentId);if(!option||!component)return toast("Selecione uma proposta para calcular a contingência.","error");let result;store.update(x=>{result=authorizeEngineeringRecovery(x,component,option);if(result.ok){x.campaign.turn=(x.campaign.turn||1)+1;x.ui.advisorMessage="Contingência autorizada. A proposta pode ser comprometida."}},`Contingência autorizada para ${component.name}`);if(result?.ok){audioCue("alarm");engineeringRecoveryModal(component,result)}else toast(result?.reason||"Contingência indisponível.","error")});
  one("[data-commit-engineering]","click",()=>{const current=store.getState(),session=engineeringData.sessions.find(item=>!(current.engineering?.locked||[]).includes(item.id)),componentId=session&&current.engineering?.drafts?.[session.id],option=session?.options.find(item=>item.componentId===componentId),component=session&&data.components[session.id]?.find(item=>item.id===componentId);if(!session||!option||!component)return toast("Selecione uma proposta antes de comprometer o projeto.","error");if(current.economy.available<component.cost)return toast("Orçamento insuficiente para esta proposta.","error");if(current.agency.politicalCapital+(option.influence||0)<0)return toast("Influência insuficiente para obter autorização.","error");let result;store.update(x=>{result=commitEngineeringDecision(x,data,session,option);if(result.ok){x.engineering.active=(x.engineering.locked||[]).length;x.campaign.turn=(x.campaign.turn||1)+1;x.ui.advisorMessage=`${component.name} comprometido. O contrato agora tem consequências.`}},`${session.label}: ${component.name} comprometido`);if(!result?.ok)return toast(result?.reason||"Não foi possível registrar a decisão.","error");audioCue("success");engineeringDecisionModal(session,option,component)});
  document.querySelectorAll("[data-reopen-engineering]").forEach(b=>b.addEventListener("click",()=>{const current=store.getState();if(current.economy.available<3)return toast("São necessários 3 bi para abrir uma revisão.","error");if(current.agency.politicalCapital<2)return toast("Influência insuficiente para reabrir o contrato.","error");let result;store.update(x=>{result=reopenEngineeringDecision(x,b.dataset.reopenEngineering);if(result.ok){x.campaign.turn=(x.campaign.turn||1)+1;x.engineering.active=(x.engineering.locked||[]).length;x.ui.advisorMessage="Revisão extraordinária aberta. O investimento anterior não será reembolsado."}},`Revisão aberta: ${b.dataset.reopenEngineering}`);if(result?.ok){toast("Contrato reaberto: −3 bi, +18 dias, −2 confiança.","error");audioCue("alarm")}else toast(result?.reason||"Revisão indisponível.","error")}));
  one("[data-program-restructure]","click",()=>{if(!confirm("Reestruturar todo o projeto? Os contratos atuais serão perdidos e haverá dívida, atraso e perda de apoio."))return;let result;store.update(x=>{result=restructureEngineeringProgram(x);x.ui.advisorMessage="Crédito emergencial liberado. Rafael reabriu as quatro decisões de arquitetura."},"Programa ARK-01 reestruturado pelo protocolo antibloqueio");if(result?.ok){audioCue("alarm");speak("rafael_design");toast(`Projeto reaberto com ${result.targetBudget} bi. Consequências registradas.`,"error")}});
  one("[data-restart-mission]","click",()=>{if(!confirm("Reiniciar toda a missão? O progresso desta linha temporal será substituído, mas suas configurações serão preservadas."))return;const current=store.getState(),next=createInitialState(`${current.meta.seed}-R${Date.now()}`,current.campaign.mode||"campaign");next.profile=structuredClone(current.profile);next.campaign.flags.videoSeen=true;next.campaign.flags.briefing=true;next.campaign.prologueStep=story.prologue.length;next.ui.route="agency";store.replace(next);router.navigate("agency");toast("Nova linha temporal iniciada. Configurações preservadas.");audioCue("success")});
  document.querySelectorAll("[data-component]").forEach(b=>b.addEventListener("click",()=>{const [category,id]=b.dataset.component.split(":"),next=data.components[category].find(c=>c.id===id),current=store.getState(),previous=data.components[category].find(c=>c.id===current.ship.design[category]),refund=previous?.cost||0;if(current.economy.available+refund<next.cost)return toast("Orçamento insuficiente para este componente.","error");store.update(x=>{x.economy.available+=refund-next.cost;x.economy.committed+=next.cost-refund;x.ship.design[category]=id},`${category}: ${id} integrado por ${next.cost} bi`)}));
  one("[data-approve-design]","click",()=>go(2,"testing","Configuração ARK-01 congelada",`${(s.ship.mass.total/1000).toFixed(1)} t; ${s.ship.deltaV} m/s delta-v`));
  document.querySelectorAll("[data-test]").forEach(b=>b.addEventListener("click",()=>{const test=data.tests.find(x=>x.id===b.dataset.test);let defect=false;store.update(x=>{defect=completeTest(x,test)},`Teste concluído: ${test.name}${defect?"; desvio detectado e mitigado":"; dentro dos limites"}`);toast(defect?"O teste revelou um modo de falha. Mitigação registrada.":"Teste nominal. Incerteza reduzida.",defect?"error":"ok")}));
  one("[data-test-recovery]","click",()=>{let result;store.update(x=>{result=authorizeTestRecovery(x,data.tests)},"Resgate financeiro do programa de testes autorizado");if(result?.ok){audioCue("alarm");toast(`Crédito de ${result.credit} bi liberado para a sequência mínima.`,"error")}else toast(result?.reason||"Resgate indisponível.","error")});
  one("[data-finish-tests]","click",()=>go(3,"crew","Certificação de ensaios",`${(s.mission.testsCompleted||[]).length} campanhas concluídas`));
  document.querySelectorAll("[data-crew-station]").forEach(b=>b.addEventListener("click",()=>store.update(x=>x.crew.activeStation=b.dataset.crewStation,`Estação aberta: ${b.dataset.crewStation}`)));
  document.querySelectorAll("[data-crew-interview]").forEach(b=>b.addEventListener("click",()=>{const station=crewOps.stations.find(item=>item.id===b.dataset.station),entry=station?.candidates.find(item=>item.id===b.dataset.crewInterview),candidate=data.crew.find(item=>item.id===b.dataset.crewInterview);if(station&&entry&&candidate)crewInterviewModal(station,entry,candidate)}));
  document.querySelectorAll("[data-crew-assign]").forEach(b=>b.addEventListener("click",()=>setCrewAssignment(b.dataset.station,b.dataset.crewAssign)));
  document.querySelectorAll("[data-crew-remove]").forEach(b=>b.addEventListener("click",()=>store.update(x=>{x.crew.assignments[b.dataset.crewRemove]=null;x.crew.activeStation=b.dataset.crewRemove;x.crew.trainingModules=[];x.crew.training=0;x.crew.legacyCertified=false},`Vaga reaberta: ${b.dataset.crewRemove}`)));
  document.querySelectorAll("[data-crew-training]").forEach(b=>b.addEventListener("click",()=>{const module=crewOps.training.find(item=>item.id===b.dataset.crewTraining);let result;store.update(x=>result=completeCrewTraining(x,module),`Treinamento concluído: ${module.label}`);if(result?.ok){audioCue("success");crewTrainingModal(module)}else toast(result?.reason||"Treinamento indisponível.","error")}));
  one("[data-finish-crew]","click",()=>go(4,"countdown","Tripulação certificada",`${s.crew.members.length} especialistas; confiança ${Math.round(s.crew.trust)}%`));
  one("[data-hold]","click",()=>{store.update(x=>{x.time.earthDate+=12;x.ship.reliability+=3;x.agency.support-=3},"Lançamento suspenso para revisão independente");toast("Janela renegociada. A confiabilidade aumentou.")});
  one("[data-launch]","click",()=>{let result;store.update(x=>{result=simulateLaunch(x);x.campaign.decisions.push({title:"Autoridade de lançamento",detail:`Risco causal estimado ${result?.risk||0}%`})},"Sequência de lançamento autorizada");if(result.failed){audioCue("alarm");cinematic("mission_failure").then(()=>speak("aura_failure")).then(showFailureSequence)}else{audioCue("success");flightCinematicMilestones.clear();store.update(x=>{x.campaign.act=5;x.mission.flightStage=0;x.mission.flight6d=createDefaultFlightState()},"Lançamento autorizado");outcomeModal("countdown","flight")}});
  document.querySelectorAll("[data-ops-accept]").forEach(button=>button.addEventListener("click",()=>{let result;store.update(x=>result=acceptOperation(x,button.dataset.opsAccept),`Contrato orbital aceito: ${button.dataset.opsAccept}`);if(result?.ok){audioCue("success");if(result.contract?.id==="rescue")speak("asha_rescue",{once:true});toast("Missão preparada. A primeira decisão está aberta.")}else toast(result?.reason||"Contrato indisponível.","error")}));
  document.querySelectorAll("[data-ops-choice]").forEach(button=>button.addEventListener("click",()=>{let result;store.update(x=>result=resolveOperationDecision(x,button.dataset.opsChoice),`Decisão operacional: ${button.dataset.opsChoice}`);if(!result?.ok)return toast(result?.reason||"Decisão indisponível.","error");audioCue(result.complete?(result.report.success?"success":"alarm"):result.resolution.success?"success":"alarm");const active=store.getState().operations?.active;if(!result.complete&&!result.resolution.success&&active?.contract?.id==="debris")cinematic("debris_impact").then(()=>speak("rafael_damage"));if(result.complete&&!result.report.success)cinematic("mission_failure").then(()=>speak("aura_failure"));toast(result.complete?(result.report.success?"Missão cumprida. Debriefing liberado.":"Missão comprometida. A cadeia causal foi preservada."):(result.resolution.success?"Procedimento dentro da margem.":"Desvio operacional: consequências aplicadas."),result.complete&&!result.report.success||!result.complete&&!result.resolution.success?"error":"ok")}));
  one("[data-ops-close-report]","click",()=>store.update(x=>closeOperationReport(x),"Relatório arquivado; novo ciclo operacional aberto"));
  one("[data-ops-refresh]","click",()=>{let result;store.update(x=>result=refreshOperationBoard(x),"Janelas orbitais recalculadas");result?.ok?toast("Novas janelas calculadas."):toast(result?.reason||"Não foi possível recalcular.","error")});
  one("[data-ops-resupply]","click",()=>{let result;store.update(x=>result=authorizeOrbitalResupply(x),"Reabastecimento orbital autorizado");result?.ok?toast(`Propelente restaurado para ${Math.round(result.propellantKg)} kg.`):toast(result?.reason||"Reabastecimento indisponível.","error")});
  one("[data-rv-reset]","click",()=>store.update(x=>resetRendezvous(x),"Nova aproximação orbital preparada"));
  if(route==="rendezvous"){
    ensureRendezvousState(s);const root=app.querySelector(".rv-simulator"),canvas=root?.querySelector("#rendezvous-canvas");
    speak("jun_rv_intro",{once:true});
    rendezvousController=createRendezvousController({root,canvas,initial:s.mission.rendezvous,reduceMotion:s.profile.accessibility.reduceMotion,onMilestone:id=>{if(id==="close")speak("jun_rv_close",{once:true})},onComplete:rv=>{const result=rv.lastResult;store.update(x=>{x.mission.rendezvous=rv;commitRendezvousResult(x,result)},result.status==="docked"?"Acoplagem orbital concluída":"Incidente de rendezvous registrado");audioCue(result.status==="docked"?"success":"alarm");const cue=result.status==="docked"?"docking_success":"docking_collision",voice=result.status==="docked"?"jun_docked":"jun_collision";cinematic(cue).then(()=>speak(voice)).then(()=>{if(result.status!=="docked")speak("rafael_damage")});}})
  }
  document.querySelectorAll("[data-nav-target]").forEach(b=>b.addEventListener("click",()=>{let result;store.update(x=>result=selectNavigationTarget(x,solarData,b.dataset.navTarget),`Destino analisado: ${b.dataset.navTarget}`);result?.ok?toast(`${result.route.targetName}: rota calculada, aguardando sua confirmação.`):toast(result?.reason||"Destino indisponível.","error")}));
