function showFlightTutorial(){openFlightTutorial({root:document,portraitHtml:portrait("jun-park")})}
function applyFlightLook(root=document){const yaw=flightLook.yawDeg||0,pitch=flightLook.pitchDeg||0,status=root.querySelector?.("[data-camera-status]");if(status)status.textContent=yaw||pitch?`VISÃO ${yaw.toFixed(0)}° / ${pitch.toFixed(0)}°`:`CÂMERA ${flightCamera.toUpperCase()}`;const yawReadout=root.querySelector?.("[data-look-yaw]"),pitchReadout=root.querySelector?.("[data-look-pitch]");if(yawReadout)yawReadout.textContent=`YAW ${yaw.toFixed(0)}°`;if(pitchReadout)pitchReadout.textContent=`PITCH ${pitch.toFixed(0)}°`;root.querySelector?.(".immersive-cockpit")?.style.setProperty("--look-yaw",`${yaw}`);root.querySelector?.(".immersive-cockpit")?.style.setProperty("--look-pitch",`${pitch}`)}
function playFlightCinematicOnce(id,voiceId){if(flightCinematicMilestones.has(id))return Promise.resolve({played:false,reason:"already-played"});flightCinematicMilestones.add(id);return cinematic(id).then(result=>voiceId?speak(voiceId).then(()=>result):result)}
