function drawLiveTrajectory(stage,progress,metrics){const canvas=document.querySelector("#trajectory-canvas");if(stage>=3)return drawOrbitMap(canvas,store.getState());const fit=dynamicCanvas(canvas);if(!fit)return;const {ctx,w,h}=fit;ctx.clearRect(0,0,w,h);ctx.fillStyle="#02090e";ctx.fillRect(0,0,w,h);ctx.strokeStyle="#153847";ctx.lineWidth=1;for(let x=0;x<w;x+=w/8){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=0;y<h;y+=h/5){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.strokeStyle="#59daf7";ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(8,h-12);ctx.bezierCurveTo(w*.2,h*.91,w*.35,h*.2,w*.62,h*.34);ctx.bezierCurveTo(w*.79,h*.43,w*.84,h*.1,w-8,12);ctx.stroke();const total=(stage+progress)/5,x=8+(w-16)*total,y=h-12-(h-24)*Math.pow(total,.72);ctx.fillStyle="#ffb84c";ctx.shadowColor="#ffb84c";ctx.shadowBlur=12;ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle="#8aa8b5";ctx.font="9px monospace";ctx.fillText(`${metrics.alt.toFixed(1)} KM`,8,13);ctx.fillText(`${Math.round(metrics.speed)} KM/H`,8,25)}
function showFailureSequence(){const media=flightManifest.failure;if(!media?.enabled)return failureModal();const wrap=document.createElement("div");wrap.className="failure-cinematic";wrap.innerHTML=`<video autoplay playsinline src="./assets/video/${esc(media.src)}"></video><div><span>TELEMETRIA PERDIDA</span><b>ABORTAGEM DA MISSÃO</b></div><button>Pular para o relatório</button>`;document.body.append(wrap);const finish=()=>{wrap.remove();failureModal()};wrap.querySelector("video").addEventListener("ended",finish,{once:true});wrap.querySelector("video").addEventListener("error",finish,{once:true});wrap.querySelector("button").addEventListener("click",finish,{once:true})}

function outcomeModal(route,nextRoute){const outcome=story.outcomes[route];if(!outcome){store.update(x=>{x.campaign.turn=(x.campaign.turn||1)+1;x.ui.route=nextRoute},"Turno encerrado");router.navigate(nextRoute);return}modal(`<div class="turn-report"><div class="report-portrait">${portrait(outcome.avatar)}</div><div><div class="eyebrow">RELATÓRIO DE DECISÃO · TURNO ${String(store.getState().campaign.turn||1).padStart(3,"0")}</div><h2>${esc(outcome.title)}</h2><div class="speaker"><b>${esc(outcome.speaker)}</b><span>CANAL DA EQUIPE</span></div><p>${esc(outcome.message)}</p><div class="consequence-strip"><span>DECISÃO REGISTRADA</span><span>ESTADO RECALCULADO</span><span>AUTOSAVE ATIVO</span></div><button class="primary" data-close-turn>Encerrar turno e continuar</button></div></div>`,()=>one("[data-close-turn]","click",()=>{closeModal();store.update(x=>{x.campaign.turn=(x.campaign.turn||1)+1;x.ui.route=nextRoute;x.ui.advisorMessage=null},`Turno ${xTurn()} encerrado`);router.navigate(nextRoute)}))}
function engineeringDecisionModal(session,option,component){const s=store.getState();modal(`<div class="engineering-report"><div class="report-portrait">${portrait("rafael-costa")}</div><div><div class="eyebrow">MEMORANDO DE CONFIGURAÇÃO · TURNO ${String((s.campaign.turn||1)-1).padStart(3,"0")}</div><h2>${esc(component.name)} está comprometido</h2><div class="speaker"><b>Eng. Rafael Costa</b><span>ENGENHEIRO-CHEFE</span></div><p>Contrato assinado, interfaces congeladas. A equipe pode contestar, mas qualquer retorno agora consumirá orçamento, prazo e confiança.</p><div class="decision-ledger"><span><small>ORÇAMENTO</small><b>−${component.cost} bi</b></span><span><small>CRONOGRAMA</small><b>+${option.days} dias</b></span><span><small>INFLUÊNCIA</small><b>${signed(option.influence)}</b></span><span><small>CONFIANÇA</small><b>${signed(option.trust)}</b></span></div><div class="risk-callout"><span>RISCO ACEITO</span><b>${esc(option.risk)}</b></div><button class="primary" data-engineering-continue>CONTINUAR PARA A PRÓXIMA REVISÃO</button></div></div>`,()=>one("[data-engineering-continue]","click",()=>{closeModal();toast(`${session.label} registrada no arquivo da missão.`)}))}
function engineeringRecoveryModal(component,result){modal(`<div class="engineering-report"><div class="report-portrait">${portrait("mateo-vega")}</div><div><div class="eyebrow">PROTOCOLO DE CONTINGÊNCIA · DECISÃO DE TURNO</div><h2>A votação foi reaberta</h2><div class="speaker"><b>Mateo Vega</b><span>DIRETOR DE VOO DA GSEA</span></div><p>Usei a reserva disponível e negociei o restante como crédito emergencial para ${esc(component.name)}. A proposta voltou a ser selecionável; o custo político permanecerá no histórico.</p><div class="decision-ledger"><span><small>VERBA LIBERADA</small><b>+${result.budgetGap} bi</b></span><span><small>RESERVA USADA</small><b>${result.reserve} bi</b></span><span><small>CRONOGRAMA</small><b>+${result.days} dias</b></span><span><small>APOIO</small><b>−${result.supportCost}</b></span></div><button class="primary" data-close-recovery>VOLTAR À PROPOSTA</button></div></div>`,()=>one("[data-close-recovery]","click",closeModal))}
function orbitalBurnModal(result){const burn=result.record;modal(`<div class="turn-report"><div class="report-portrait">${portrait("jun-park")}</div><div><div class="eyebrow">RELATÓRIO DE MANOBRA · ${esc(burn.id)}</div><h2>${esc(burn.label)} concluída</h2><div class="speaker"><b>Jun Park</b><span>PILOTO · NAVEGAÇÃO ORBITAL</span></div><p>A telemetria pós-queima foi ajustada pelo mesmo estado físico que alimenta os instrumentos da cabine. A órbita e o propelente foram recalculados pela equação vis-viva e pela equação do foguete.</p><div class="decision-ledger"><span><small>DELTA-V</small><b>${burn.deltaVMps} m/s</b></span><span><small>CONSUMO</small><b>${burn.propellantUsedKg} kg</b></span><span><small>RESTANTE</small><b>${burn.remainingKg} kg</b></span><span><small>ALTITUDE</small><b>${result.snapshot.altitudeKm.toFixed(1)} km</b></span></div><button class="primary" data-close-burn>VOLTAR À CABINE</button></div></div>`,()=>one("[data-close-burn]","click",closeModal))}
function setCrewAssignment(stationId,candidateId){let result;store.update(x=>{result=assignCrewMember(x,stationId,candidateId,crewOps);if(result.ok){const next=crewOps.stations.find(item=>!x.crew.assignments[item.id]);x.crew.activeStation=next?.id||stationId;x.ui.advisorMessage="Designação registrada. A composição coletiva foi recalculada."}},`Designação de tripulação: ${candidateId} em ${stationId}`);if(result?.ok){audioCue("success");toast("Estação preenchida. Coesão e conflitos recalculados.")}else toast(result?.reason||"Designação indisponível.","error")}
function crewInterviewModal(station,entry,candidate){const profile=crewOps.profiles[candidate.id],interviewer=station.interviewer;modal(`<div class="crew-interview"><div class="interview-header"><div class="interviewer-photo">${portrait(interviewer.avatar)}</div><div><div class="eyebrow">ENTREVISTA DE MISSÃO · ${esc(station.code)}</div><h2>${esc(candidate.name)}</h2><div class="speaker"><b>${esc(interviewer.name)}</b><span>${esc(interviewer.role)}</span></div><p>${esc(profile.summary)}</p></div><div class="candidate-interview-photo">${portrait(crewPortrait[candidate.id])}<b>${entry.fit}% aderência</b></div></div><section class="interview-exchange"><span>PERGUNTA DO PAINEL</span><p>“${esc(profile.question)}”</p><span>RESPOSTA DO CANDIDATO</span><blockquote>${esc(profile.answer)}</blockquote></section><div class="interview-findings"><div><span>FORÇA</span><b>${esc(profile.strength)}</b></div><div class="warning"><span>RISCO HUMANO</span><b>${esc(profile.concern)}</b></div><div><span>VALORES</span><b>${esc(profile.values)}</b></div></div><div class="card-actions"><button data-record-interview>Registrar e voltar</button><button class="primary" data-approve-candidate>APROVAR E DESIGNAR PARA ${esc(station.code)}</button></div></div>`,()=>{const record=assign=>{store.update(x=>{if(!x.crew.interviewed.includes(candidate.id))x.crew.interviewed.push(candidate.id)},`Entrevista concluída: ${candidate.name}`);closeModal();if(assign)setCrewAssignment(station.id,candidate.id);else toast("Entrevista registrada no dossiê.")};one("[data-record-interview]","click",()=>record(false));one("[data-approve-candidate]","click",()=>record(true))})}
function crewTrainingModal(module){const lead=data.crew.find(c=>c.id===module.lead),portraitId=crewPortrait[module.lead];modal(`<div class="turn-report"><div class="report-portrait">${portrait(portraitId)}</div><div><div class="eyebrow">RELATÓRIO DE SIMULAÇÃO · ${esc(module.label.toUpperCase())}</div><h2>O erro apareceu antes do voo</h2><div class="speaker"><b>${esc(lead?.name||"Equipe ARK-01")}</b><span>LIDERANÇA DO EXERCÍCIO</span></div><p>${esc(module.briefing)} A equipe concluiu o debriefing, redistribuiu autoridade e registrou as falhas sem punição individual.</p><div class="decision-ledger"><span><small>CRONOGRAMA</small><b>+${module.days} dias</b></span><span><small>ORÇAMENTO</small><b>−${module.cost} bi</b></span><span><small>CONFIANÇA</small><b>${signed(module.trust)}</b></span><span><small>FADIGA</small><b>+4 cada</b></span></div><button class="primary" data-close-training>CONTINUAR CERTIFICAÇÃO</button></div></div>`,()=>one("[data-close-training]","click",closeModal))}
function xTurn(){return String((store.getState().campaign.turn||1)+1).padStart(3,"0")}
function failureModal(){modal(`<div class="eyebrow">ABORTAGEM AUTOMÁTICA</div><h2>Empuxo assimétrico detectado</h2><p>A votação dos sensores P-3/P-4 apontou divergência de pressão. A propagação foi interrompida antes da estrutura primária.</p><div class="card"><h3>Cadeia causal</h3><p>Turbobomba → combustão instável → vibração longitudinal → comando de corte → separação segura.</p></div><button class="primary" data-recover>Investigar, corrigir e tentar nova janela</button>`,()=>one("[data-recover]","click",()=>{store.update(x=>{x.ship.reliability+=8;x.time.earthDate+=24;x.economy.available-=4;x.mission.phase="planejamento"},"Causa raiz mitigada após abortagem");closeModal();router.navigate("countdown")}))}
function eventModal(event){modal(`<div class="event-brief"><div class="report-portrait">${portrait("asha-rao")}</div><div><div class="eyebrow">MENSAGEM DA TRIPULAÇÃO · DECISÃO DE TURNO</div><h2>${event.title}</h2><div class="speaker"><b>Dra. Asha Rao</b><span>MÉDICA DA MISSÃO</span></div><p>${event.body}</p></div></div><div class="choice-grid">${event.choices.map((c,i)=>`<button data-event-choice="${i}">${c.label}</button>`).join("")}</div>`,()=>document.querySelectorAll("[data-event-choice]").forEach(b=>b.addEventListener("click",()=>{const c=event.choices[+b.dataset.eventChoice];store.update(x=>{applyEventChoice(x,c);x.campaign.turn=(x.campaign.turn||1)+1},`${event.title}: ${c.label}`);closeModal()})))}
function codexModal(){modal(missionCodexView(store.getState()),()=>{const input=document.querySelector("[data-codex-search]"),entries=[...document.querySelectorAll("[data-codex-entry]")];input?.addEventListener("input",()=>{const query=input.value.trim().toLocaleLowerCase("pt-BR");entries.forEach(entry=>entry.hidden=query&&!entry.textContent.toLocaleLowerCase("pt-BR").includes(query))});input?.focus()})}
function injectFailure(type){setMusicScene("failure");store.update(x=>{x.ui.simFailure=type;if(type==="co2")x.systems.lifeSupport.co2ppm=4900;if(type==="power")x.systems.power.batterySoc=18;if(type==="thermal")x.systems.thermal.coreTemp=1080;if(type==="hull"){x.ship.integrity=61;x.systems.lifeSupport.cabinPressure=91.5}x.logs.failures.unshift({cause:{co2:"Saturação do leito de hidróxido",power:"Curto no barramento B",thermal:"Atuador do radiador travado",hull:"Impacto de micrometeoro"}[type],factors:["desgaste","redundância parcial"],symptoms:["telemetria fora da faixa"],propagation:"Carga secundária ameaçada",detection:"Tendência e votação de sensores",mitigation:"Isolar, transferir carga e reparar"})},`Falha injetada: ${type}`);audioCue("alarm");if(type==="hull")cinematic("debris_impact").then(()=>speak("rafael_damage"));else speak("aura_failure")}
function mitigateFailure(){store.update(x=>{const type=x.ui.simFailure;if(type==="co2")x.systems.lifeSupport.co2ppm=760;if(type==="power")x.systems.power.batterySoc=72;if(type==="thermal")x.systems.thermal.coreTemp=510;if(type==="hull"){x.ship.integrity=79;x.systems.lifeSupport.cabinPressure=100.7}x.ui.simFailure=null},"Procedimento de mitigação concluído");setMusicScene(router.current());audioCue("success")}

function renderEnding(ending){setMusicScene("ending");app.innerHTML=`<main class="ending"><article><div class="eyebrow">EPÍLOGO · PROJECT HAVEN</div><h1>${ending.title}</h1><p>${ending.body}</p><div class="scoreline">${Object.entries(ending.scores).map(([k,v])=>`<span class="chip">${k} ${Math.round(v)}</span>`).join("")}</div><div class="card-actions" style="justify-content:center"><button data-memorial>Ver memorial</button><button class="primary" data-new-cycle>Nova linha temporal</button></div></article></main>`;one("[data-memorial]","click",()=>router.navigate("memorial"));one("[data-new-cycle]","click",()=>router.navigate("menu"));saveGame("autosave",store.getState())}
function settingsModal(){const s=store.getState(),mix=normalizeAudioMix(s.profile.audioMix);modal(`<div class="eyebrow">INTERFACE, SOM E ACESSIBILIDADE</div><h2>${t("settings")}</h2><div class="form-row"><div class="field"><label>Idioma</label><select id="lang"><option value="pt-BR" ${locale==="pt-BR"?"selected":""}>Português (Brasil)</option><option value="en" ${locale==="en"?"selected":""}>English</option><option value="es" ${locale==="es"?"selected":""}>Español</option></select></div><div class="field"><label>Sistema de áudio</label><select id="audio"><option value="on" ${s.profile.audio?"selected":""}>Ativo</option><option value="off" ${!s.profile.audio?"selected":""}>Silenciar tudo</option></select></div></div><section class="audio-mixer"><div><label for="music-volume">MÚSICA DE FUNDO <small>reduz automaticamente durante falas</small></label><input id="music-volume" data-audio-range type="range" min="0" max="100" value="${mix.music}"><output>${mix.music}%</output></div><div><label for="voice-volume">FALAS DA EQUIPE <small>prioridade sobre a trilha</small></label><input id="voice-volume" data-audio-range type="range" min="0" max="100" value="${mix.voices}"><output>${mix.voices}%</output></div><div><label for="effects-volume">EFEITOS E VÍDEOS <small>motor, alarmes e cenas</small></label><input id="effects-volume" data-audio-range type="range" min="0" max="100" value="${mix.effects}"><output>${mix.effects}%</output></div></section><div class="choice-grid" style="margin-top:.8rem"><label class="card"><input type="checkbox" id="contrast" ${s.profile.accessibility.highContrast?"checked":""}> Alto contraste</label><label class="card"><input type="checkbox" id="large" ${s.profile.accessibility.largeText?"checked":""}> Texto ampliado</label><label class="card"><input type="checkbox" id="motion" ${s.profile.accessibility.reduceMotion?"checked":""}> Reduzir movimento</label><label class="card"><input type="checkbox" id="colorblind" ${s.profile.accessibility.colorblind?"checked":""}> Paleta daltônica</label></div><button class="primary" data-apply-settings>APLICAR MIXAGEM</button>`,()=>{document.querySelectorAll("[data-audio-range]").forEach(input=>input.addEventListener("input",()=>input.nextElementSibling.textContent=`${input.value}%`));one("[data-apply-settings]","click",()=>{locale=document.querySelector("#lang").value;localStorage.setItem("lh-locale",locale);const audioMix={music:Number(document.querySelector("#music-volume").value),voices:Number(document.querySelector("#voice-volume").value),effects:Number(document.querySelector("#effects-volume").value)},enabled=document.querySelector("#audio").value==="on";store.update(x=>{x.profile.language=locale;x.profile.audio=enabled;x.profile.audioMix=audioMix;x.profile.accessibility={highContrast:document.querySelector("#contrast").checked,largeText:document.querySelector("#large").checked,reduceMotion:document.querySelector("#motion").checked,colorblind:document.querySelector("#colorblind").checked}},"Preferências de som e acessibilidade atualizadas");setAudioMix(enabled?audioMix:{music:0,voices:0,effects:0});closeModal();router.navigate(router.current())})})}
async function saveModal(){const rows=await listSaves();modal(`<div class="eyebrow">ARQUIVO LOCAL CRIPTOGRAFICAMENTE VERIFICADO</div><h2>${t("saves")}</h2><div class="grid">${rows.map(r=>`<article class="card"><h3>${esc(r.name)}</h3><p>${new Date(r.updatedAt).toLocaleString()} · ${esc(r.payload?.profile?.directorName||"")}</p><div class="card-actions"><button data-load="${esc(r.slot)}">Carregar</button><button data-delete="${esc(r.slot)}" class="danger">Excluir</button></div></article>`).join("")||'<p class="muted">Nenhuma partida armazenada.</p>'}</div><div class="card-actions"><button data-save-slot>Salvar no slot 1</button><button data-export>Exportar JSON</button><label class="card" style="cursor:pointer">Importar JSON<input class="sr-only" type="file" id="import-save" accept="application/json"></label></div>`,()=>{
    document.querySelectorAll("[data-load]").forEach(b=>b.addEventListener("click",async()=>{try{store.replace(await loadGame(b.dataset.load));closeModal();router.navigate(store.getState().ui.route||"agency")}catch(e){toast(e.message,"error")}}));
    document.querySelectorAll("[data-delete]").forEach(b=>b.addEventListener("click",async()=>{if(confirm("Excluir este slot? A exportação externa não será afetada.")){await deleteSave(b.dataset.delete);closeModal();saveModal()}}));
    one("[data-save-slot]","click",async()=>{await saveGame("1",store.getState());localStorage.setItem("lh-has-save","1");closeModal();toast("Slot 1 salvo com checksum")});one("[data-export]","click",()=>exportGame(store.getState()));
    one("#import-save","change",async e=>{try{store.replace(await importGame(e.target.files[0]));closeModal();router.navigate(store.getState().ui.route||"agency");toast("Save importado e migrado") }catch(err){toast(err.message,"error")}});
  })}
function modal(content,onOpen){const wrap=document.createElement("div");wrap.className="modal-backdrop";wrap.innerHTML=`<section class="modal" role="dialog" aria-modal="true"><header><span></span><button data-close aria-label="Fechar">×</button></header>${content}</section>`;document.body.append(wrap);wrap.querySelectorAll("[data-close]").forEach(b=>b.addEventListener("click",()=>wrap.remove()));wrap.addEventListener("click",e=>{if(e.target===wrap)wrap.remove()});onOpen?.();wrap.querySelector("input,select,button")?.focus()}
function closeModal(){document.querySelector(".modal-backdrop")?.remove()}
function one(selector,event,handler){document.querySelector(selector)?.addEventListener(event,handler)}

function fitCanvas(canvas){if(!canvas)return null;const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio,2);canvas.width=Math.max(1,rect.width*dpr);canvas.height=Math.max(1,rect.height*dpr);const ctx=canvas.getContext("2d");ctx.scale(dpr,dpr);return {ctx,w:rect.width,h:rect.height}}
function drawTrajectory(){const canvas=document.querySelector("#trajectory-canvas"),fit=fitCanvas(canvas);if(!fit)return;const {ctx,w,h}=fit,stage=store.getState().mission.flightStage||0;ctx.clearRect(0,0,w,h);ctx.strokeStyle="#183d4d";ctx.lineWidth=1;for(let x=0;x<w;x+=w/8){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=0;y<h;y+=h/5){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.strokeStyle="#65e6ff";ctx.lineWidth=2;ctx.shadowColor="#2bd8ff";ctx.shadowBlur=10;ctx.beginPath();ctx.moveTo(12,h-18);ctx.bezierCurveTo(w*.23,h*.93,w*.35,h*.25,w*.63,h*.35);ctx.bezierCurveTo(w*.78,h*.4,w*.82,h*.1,w-12,18);ctx.stroke();const progress=Math.min(1,(stage+1)/5),x=12+(w-24)*progress,y=h-18-(h-36)*Math.pow(progress,.72);ctx.fillStyle="#ffb84c";ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fill()}
function drawSystem(){const canvas=document.querySelector("#system-canvas"),fit=fitCanvas(canvas);if(!fit)return;const {ctx,w,h}=fit,s=store.getState(),seed=s.meta.rngState||1,cx=w*.45,cy=h*.52;ctx.clearRect(0,0,w,h);for(let i=0;i<80;i++){const x=(i*71+seed%97)%w,y=(i*43+seed%61)%h;ctx.fillStyle=`rgba(180,230,255,${.15+(i%5)*.08})`;ctx.fillRect(x,y,1,1)}const glow=ctx.createRadialGradient(cx,cy,0,cx,cy,44);glow.addColorStop(0,"#fff7ca");glow.addColorStop(.18,"#ffd16a");glow.addColorStop(1,"rgba(255,170,40,0)");ctx.fillStyle=glow;ctx.beginPath();ctx.arc(cx,cy,44,0,Math.PI*2);ctx.fill();[.19,.31,.44].forEach((r,i)=>{ctx.strokeStyle="rgba(92,208,239,.3)";ctx.beginPath();ctx.ellipse(cx,cy,w*r,h*r*.55,0,0,Math.PI*2);ctx.stroke();const a=((seed%360)+i*117)*Math.PI/180,px=cx+Math.cos(a)*w*r,py=cy+Math.sin(a)*h*r*.55;ctx.fillStyle=["#6ed4c9","#66a9ef","#d57152"][i];ctx.beginPath();ctx.arc(px,py,6+i*2,0,Math.PI*2);ctx.fill()})}
function drawSpace(){const c=document.querySelector("#space-canvas"),ctx=c.getContext("2d"),dpr=Math.min(devicePixelRatio,2);c.width=innerWidth*dpr;c.height=innerHeight*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,innerWidth,innerHeight);const rand=i=>((i*9301+49297)%233280)/233280;for(let i=0;i<160;i++){const x=rand(i)*innerWidth,y=rand(i+251)*innerHeight,r=rand(i+13)*1.2+.2;ctx.fillStyle=`rgba(160,225,255,${.18+rand(i+99)*.55})`;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}}
addEventListener("resize",()=>{drawSpace();drawTrajectory();drawSystem()});drawSpace();
store.subscribe(state=>{lastState=state;applyAccessibility(state);setAudioMix(state.profile.audio===false?{music:0,voices:0,effects:0}:state.profile.audioMix);const route=router.current();if(route==="prologue")prologue();else if(route!=="menu"&&route!=="ending")shell(route);clearTimeout(autosaveTimer);autosaveTimer=setTimeout(()=>{const test=state.meta?.testMode?.enabled===true;saveGame(test?"test-autosave":"autosave",state);localStorage.setItem(test?"lh-has-test-save":"lh-has-save","1")},650)});
const router=createRouter(route=>{if(route==="menu")menu();else if(route==="prologue")prologue();else if(route==="ending")renderEnding(endingFor(store.getState()));else shell(route)});
applyAccessibility(store.getState());router.start();
if("serviceWorker" in navigator&&location.protocol.startsWith("http"))navigator.serviceWorker.register("./service-worker.js",{updateViaCache:"none"}).then(registration=>registration.update()).catch(()=>{});
